SysDataModelXML.JavaScript:
scan_para = function (id, r) {
    if (id == "linkinput") {
        scan_impl(id, "#" + r + "#");
    }
    else {
        document.getElementById(id).value = r;
    }
};

//扫描状态正常直接查询，不正常跳框提示
scanAfterAction = function (id) {
    if ($("#数据检查").val() !== "") {
        alert($("#数据检查").val());
        return;
    }
    var dmPara = reParaList(); // 获取界面上的参数
    showModelData(dmPara); // 触发查询
};


beforeFunction = function (sta, id) {
    var a = $("#数据检查").val();
    if ((a != "OK") && (sta == "new" || sta == "autoSave")) {
        alert(a);
        return true;
    }

    if (id == "linkok") {
        var 退料数量 = parseFloat($("#退料数量").val());
        // 获取序列号的值
        var 序列号 = $("#序列号").val().trim();

        // 如果序列号不为空，则领料数量只能为1
        if (序列号 != "" && 退料数量 != 1) {
            alert("lang:{zh:存在序列号，退料数量只能为1,en:Serial number exists, return quantity must be 1,de:Seriennummer vorhanden, Rückgabemenge muss 1 sein}");
            $("#退料数量").focus();
            return false;
        }
        // 分别判断
        if (退料数量 <= 0) {
            alert("lang:{zh:退料数量必须大于0,en:Return quantity must be greater than 0,de:Rückgabemenge muss größer als 0 sein}");
            $("#退料数量").focus();
            return true;
        }

    }
    return false;
};

repeatTime = function (id) {
    if (id == "linkpreprocess")
        return 15
    return 1
}

limitTimeAction = function (id) {
    if (id == "linkpreprocess")
        alert("lang:{zh:15秒内不可重复点击,en:Cannot click repeatedly within 15 seconds,de:Innerhalb 15 Sekunden nicht wiederholt klicken}");
}

//删除后自动刷新
afterFunction = function (id) {
    if (id == "linkquick12")
        reloadModelData()
}
